JD("js/effekt_runtime.js",'\n// Sentinel: a node whose .value is Mem is the current root.\nconst Mem \x3d null\n\n// reusable buffer for rerooting\nconst _rerootPath \x3d []\n\n/**\n * A mutable reference inside an `Arena`.\n */\nclass Ref {\n  constructor(v, s) {\n    this.value \x3d v;\n    this.generation \x3d s.generation;\n    this.store \x3d s;\n  }\n\n  set(v) {\n    const s     \x3d this.store;\n    const r_gen \x3d this.generation;\n    const s_gen \x3d s.generation;\n    if (r_gen \x3d\x3d\x3d s_gen) {\n      this.value \x3d v;\n    } else {\n      const root   \x3d { value: Mem };\n      s.root.value \x3d { ref: this, value: this.value, generation: r_gen, root };\n\n      s.root          \x3d root;\n      this.value      \x3d v;\n      this.generation \x3d s_gen;\n    }\n  }\n}\n\n/**\n * A snapshottable arena: a bag of `Ref`s whose collective state can be\n * captured in O(1) and restored in O(#writes since capture).\n */\nclass Arena {\n  constructor() {\n    this.root       \x3d { value: Mem };\n    this.generation \x3d 0;\n  }\n\n  /**\n   * Allocate a new reference with initial value v.\n   */\n  fresh(v) {\n    return new Ref(v, this);\n  }\n\n  /**\n   * Region support (not implemented!).\n   */\n  newRegion() {\n    return this;\n  }\n}\n\nfunction snapshot(s) {\n  if (s \x3d\x3d\x3d null) return null\n  const snap \x3d { store: s, root: s.root, generation: s.generation }\n  s.generation \x3d s.generation + 1\n  return snap\n}\n\nfunction reroot(target) {\n  // 1. Walk from target toward the Mem node, collecting the path into `_rerootPath`\n  _rerootPath.length \x3d 0\n  let cur \x3d target\n  while (cur.value !\x3d\x3d Mem) {\n    _rerootPath.push(cur)\n    cur \x3d cur.value.root\n  }\n  // cur is now Mem (the current root)\n\n  // 2. Walk back from current root toward target,\n  //    reverse each edge, restore each ref.\n  for (let i \x3d _rerootPath.length - 1; i \x3e\x3d 0; i--) {\n    const node   \x3d _rerootPath[i]\n    const diff   \x3d node.value // forward diff\n    const r      \x3d diff.ref\n    cur.value    \x3d { ref: r, value: r.value, generation: r.generation, root: node }\n    r.value      \x3d diff.value      // restore ref\'s old value\n    r.generation \x3d diff.generation //  ... and old generation\n    node.value   \x3d Mem\n    cur          \x3d node\n  }\n\n  // 3. Reclaim the path to reuse the buffer eagerly\n  _rerootPath.length \x3d 0\n}\n\nfunction restore(store, snap) {\n  if (snap \x3d\x3d\x3d null) return // nothing saved ~\x3e nothing to restore\n  if (snap.root.value !\x3d\x3d Mem) {\n    // fast path: continuation is resumed immediately with no writes in between\n    reroot(snap.root)\n    store.root \x3d snap.root\n  }\n  store.generation \x3d snap.generation + 1\n}\n\n// Common Runtime\n// --------------\nconst TOPLEVEL_K \x3d (x, ks) \x3d\x3e { throw { computationIsDone: true, result: x } }\nconst TOPLEVEL_KS \x3d { stack: null, prompt: Symbol("toplevel"), arena: null, rest: null }\n\n// The first variable in a scope creates its arena; until then `ks.arena` is null.\nfunction VAR(init, ks) {\n  const arena \x3d ks.arena !\x3d\x3d null ? ks.arena : (ks.arena \x3d new Arena())\n  return arena.fresh(init)\n}\n\nfunction REGION(ks) {\n  const arena \x3d ks.arena !\x3d\x3d null ? ks.arena : (ks.arena \x3d new Arena())\n  return arena.newRegion()\n}\n\nfunction THUNK(f) {\n  f.thunk \x3d true\n  return f\n}\n\nfunction CAPTURE(body) {\n  return (ks, k) \x3d\x3e {\n    const res \x3d body(x \x3d\x3e TRAMPOLINE(() \x3d\x3e k(x, ks)))\n    if (typeof res \x3d\x3d\x3d "function") return res\n    else throw { computationIsDone: true, result: $effekt.unit }\n  }\n}\n\nconst RETURN \x3d (x, ks) \x3d\x3e ks.rest.stack(x, ks.rest)\n\n// HANDLE(ks, ks, (p, ks, k) \x3d\x3e { STMT })\nfunction RESET(prog, ks, k) {\n  const prompt \x3d Symbol(); // gensym\n  const rest \x3d { stack: k, prompt: ks.prompt, arena: ks.arena, rest: ks.rest }\n  return prog(prompt, { stack: null, prompt, arena: null, rest }, RETURN)\n}\n\nfunction SHIFT(p, body, ks, k) {\n\n  // TODO avoid constructing this object\n  let meta \x3d { stack: k, prompt: ks.prompt, arena: ks.arena, rest: ks.rest }\n  let cont \x3d null\n\n  while (!!meta \x26\x26 meta.prompt !\x3d\x3d p) {\n    let store \x3d meta.arena\n    cont \x3d { stack: meta.stack, prompt: meta.prompt, arena: store, backup: snapshot(store), rest: cont }\n    meta \x3d meta.rest\n  }\n  if (!meta) { throw `Prompt not found ${p}` }\n\n  // package the prompt itself\n  let store \x3d meta.arena\n  cont \x3d { stack: meta.stack, prompt: meta.prompt, arena: store, backup: snapshot(store), rest: cont }\n  meta \x3d meta.rest\n\n  const k1 \x3d meta.stack\n  meta.stack \x3d null\n  return body(cont, meta, k1)\n}\n\n// Rewind stack `cont` back onto `k` :: `ks` and resume with c\nfunction RESUME(cont, c, ks, k) {\n  let meta \x3d { stack: k, prompt: ks.prompt, arena: ks.arena, rest: ks.rest }\n  let toRewind \x3d cont\n  while (!!toRewind) {\n    restore(toRewind.arena, toRewind.backup)\n    meta \x3d { stack: toRewind.stack, prompt: toRewind.prompt, arena: toRewind.arena, rest: meta }\n    toRewind \x3d toRewind.rest\n  }\n\n  const k1 \x3d meta.stack // TODO instead copy meta here, like elsewhere?\n  meta.stack \x3d null\n  return () \x3d\x3e c(meta, k1)\n}\n\nfunction RUN_TOPLEVEL(comp) {\n  try {\n    let a \x3d comp(TOPLEVEL_KS, TOPLEVEL_K)\n    while (true) { a \x3d a() }\n  } catch (e) {\n    if (e.computationIsDone) return e.result\n    else throw e\n  }\n}\n\n// trampolines the given computation (like RUN_TOPLEVEL, but doesn\'t provide continuations)\nfunction TRAMPOLINE(comp) {\n  let a \x3d comp;\n  try {\n    while (true) {\n      a \x3d a()\n    }\n  } catch (e) {\n    if (e.computationIsDone) return e.result\n    else throw e\n  }\n}\n\n// keeps the current trampoline going and dispatches the given task\nfunction RUN(task) {\n  return () \x3d\x3e task(TOPLEVEL_KS, TOPLEVEL_K)\n}\n\n// aborts the current continuation\nfunction ABORT(value) {\n  throw { computationIsDone: true, result: value }\n}\n\n\n// "Public API" used in FFI\n// ------------------------\n\n/**\n * Captures the current continuation as a WHOLE and makes it available\n * as argument to the passed body. For example:\n *\n *   $effekt.capture(k \x3d\x3e ... k(42) ...)\n *\n * The body\n *\n *   $effekt.capture(k \x3d\x3e \x3e\x3e\x3e ... \x3c\x3c\x3c)\n *\n * conceptually runs on the _native_ JS call stack. You can call JS functions,\n * like `setTimeout` etc., but you are not expected or required to return an\n * Effekt value like `$effekt.unit`. If you want to run an Effekt computation\n * like in `io::spawn`, you can use `$effekt.run`.\n *\n * Advanced usage details:\n *\n * The value returned by the function passed to `capture` returns\n * - a function: the returned function will be passed to the\n *   Effekt runtime, which performs trampolining.\n *   In this case, the Effekt runtime will keep running, though the\n *   continuation has been removed.\n *\n * - another value (like `undefined`): the Effekt runtime will terminate.\n */\n$effekt.capture \x3d CAPTURE\n\n/**\n * Used to call Effekt function arguments in the JS FFI, like in `io::spawn`.\n *\n * Requires an active Effekt runtime (trampoline).\n */\n$effekt.run \x3d RUN\n\n/**\n * Used to call Effekt function arguments in the JS FFI, like in `network::listen`.\n *\n * This function should be used when _no_ Effekt runtime is available. For instance,\n * in callbacks passed to the NodeJS eventloop.\n *\n * If a runtime is available, use `$effekt.run`, instead.\n */\n$effekt.runToplevel \x3d RUN_TOPLEVEL\n');
